challenge.solution:
지도 = ["*...",
        "..*.",
        "....",
        ".*.*"]
줄 = int(input("줄 번호: "))
칸 = int(input("칸 번호: "))
개수 = 0
for 옆줄 in range(줄 - 1, 줄 + 2):
    for 옆칸 in range(칸 - 1, 칸 + 2):
        if 옆줄 >= 0 and 옆줄 < len(지도) and 옆칸 >= 0 and 옆칸 < len(지도[0]):
            if 지도[옆줄][옆칸] == "*":
                개수 += 1
print(개수, "개")
